with open(SATURN_JS, 'r', encoding='utf-8') as f:
    content = f.read()

signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    taurus_json = "\n      Taurus: " + json.dumps(taurus_data, indent=8) + ","
    new_content = content[:insertion_point] + taurus_json + content[insertion_point:]
    
    with open(SATURN_JS, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("Added Saturn in Taurus to saturn.js")
else:
    print("Could not find signs object in saturn.js")
